1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	/**
59	 * A fractional amount is always rounded in the MHPCO's favour, once, at the end
60	 * of the calculation it concludes. Which direction that is depends on who pays:
61	 * the customer pays a premium, so it rounds up; the MHPCO pays a claim, so it
62	 * rounds down. Intermediate amounts stay fractional.
63	 */
64	const roundPremiumInMHPCOsFavour = Math.ceil;
65	const roundPayoutInMHPCOsFavour = Math.floor;
66	
67	const BASE_PREMIUMS: Record<string, number> = {
68	  sword: 100,
69	  amulet: 60,
70	  staff: 80,
71	  potion: 40,
72	  rune: 25,
73	  moonstone: 25,
74	};
75	
76	/** Components are the small parts — runes, moonstones — as opposed to main items. */
77	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
78	
79	/** The block discount is a components-only offer. */
80	const ALIKE_ITEMS_BLOCK = { size: 3, basePremium: 60 };
81	
82	const formsBlock = (type: string, count: number): boolean =>
83	  COMPONENT_TYPES.has(type) && count === ALIKE_ITEMS_BLOCK.size;
84	
85	const basePremiumForItemType = (type: string, count: number): number =>
86	  formsBlock(type, count)
87	    ? ALIKE_ITEMS_BLOCK.basePremium
88	    : count * BASE_PREMIUMS[type];
89	
90	/**
91	 * Tallies a list of type names. Callers project their own shape onto the type
92	 * it names, so a policy's items and a claim's damages — which spell the field
93	 * differently — can be counted by the same rule and compared.
94	 */
95	const countByType = (types: readonly string[]): Map<string, number> =>
96	  types.reduce(
97	    (counts, type) => counts.set(type, (counts.get(type) ?? 0) + 1),
98	    new Map<string, number>(),
99	  );
100	
101	const policyBasePremium = (items: Item[]): number =>
102	  [...countByType(items.map((item) => item.type))].reduce(
103	    (total, [type, count]) => total + basePremiumForItemType(type, count),
104	    0,
105	  );
106	
107	const CURSE_SURCHARGE_RATE = 0.5;
108	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
109	const HIGH_ENCHANTMENT_LEVEL = 5;
110	
111	const isHighlyEnchanted = (item: Item): boolean =>
112	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
113	
114	interface RiskFactor {
115	  applies: (item: Item) => boolean;
116	  rate: number;
117	}
118	
119	const RISK_FACTORS: RiskFactor[] = [
120	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
121	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
122	];
123	
124	const itemRiskSurcharge = (item: Item): number =>
125	  RISK_FACTORS.reduce(
126	    (total, { applies, rate }) =>
127	      applies(item) ? total + BASE_PREMIUMS[item.type] * rate : total,
128	    0,
129	  );
130	
131	const totalRiskSurcharges = (items: Item[]): number =>
132	  items.reduce((total, item) => total + itemRiskSurcharge(item), 0);
133	
134	const LOYALTY_DISCOUNT_RATE = -0.2;
135	const LOYALTY_YEARS = 2;
136	
137	const isLoyal = (customer: Customer): boolean =>
138	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
139	
140	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
141	
142	/** A quote in the context of the customer's history with the MHPCO. */
143	interface Contract {
144	  customer: Customer;
145	  /** Zero-based ordinal of this quote among the customer's quotes. */
146	  ordinal: number;
147	}
148	
149	const isFollowUpContract = (contract: Contract): boolean =>
150	  contract.ordinal > 0;
151	
152	/**
153	 * Policy-wide modifiers are charged on the policy base premium, unlike the
154	 * item-specific RISK_FACTORS which are charged on each affected item's own
155	 * base premium. Rates are signed: negative is a discount.
156	 */
157	interface PolicyFactor {
158	  applies: (contract: Contract) => boolean;
159	  rate: number;
160	}
161	
162	const POLICY_FACTORS: PolicyFactor[] = [
163	  {
164	    applies: ({ customer }) => isLoyal(customer),
165	    rate: LOYALTY_DISCOUNT_RATE,
166	  },
167	  { applies: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
168	  {
169	    applies: isFollowUpContract,
170	    rate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
171	  },
172	];
173	
174	const totalPolicyAdjustments = (
175	  policyBase: number,
176	  contract: Contract,
177	): number =>
178	  POLICY_FACTORS.reduce(
179	    (total, { applies, rate }) =>
180	      applies(contract) ? total + policyBase * rate : total,
181	    0,
182	  );
183	
184	/** The MHPCO only insures what is on its price list. */
185	const rejectUnknownItemTypes = (items: Item[]): void => {
186	  for (const item of items) {
187	    if (!(item.type in BASE_PREMIUMS)) {
188	      throw new ClaimOfficeError(
189	        `the MHPCO does not insure items of type ${item.type}`,
190	      );
191	    }
192	  }
193	};
194	
195	const quotePremium = (items: Item[], contract: Contract): number => {
196	  rejectUnknownItemTypes(items);
197	  const policyBase = policyBasePremium(items);
198	  return roundPremiumInMHPCOsFavour(
199	    policyBase +
200	      totalRiskSurcharges(items) +
201	      totalPolicyAdjustments(policyBase, contract) +
202	      PROCESSING_FEE,
203	  );
204	};
205	
206	const INSURANCE_VALUES: Record<string, number> = {
207	  sword: 1000,
208	  amulet: 600,
209	  staff: 800,
210	  potion: 400,
211	  rune: 250,
212	  moonstone: 250,
213	};
214	
215	const DEDUCTIBLE_PER_DAMAGE = 100;
216	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
217	
218	const insuranceSum = (items: Item[]): number =>
219	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
220	
221	const payoutCap = (items: Item[]): number =>
222	  insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
223	
224	/**
225	 * Distinct from the premium side's HIGH_ENCHANTMENT_LEVEL of 5: the payout
226	 * rule and the surcharge rule share a shape but not a threshold.
227	 */
228	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
229	const HALF_REIMBURSEMENT_RATE = 0.5;
230	const FULL_REIMBURSEMENT_RATE = 1;
231	
232	/**
233	 * The share of a damage amount the MHPCO reimburses, before the deductible.
234	 * Damage to a heavily enchanted item is reimbursed at half.
235	 */
236	const reimbursementRate = (item: Item): number =>
237	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
238	    ? HALF_REIMBURSEMENT_RATE
239	    : FULL_REIMBURSEMENT_RATE;
240	
241	const damagePayout = (damage: Damage, policyItems: Item[]): number => {
242	  const damagedItem = policyItems.find(
243	    (item) => item.type === damage.itemType,
244	  ) as Item;
245	  return damage.amount * reimbursementRate(damagedItem) - DEDUCTIBLE_PER_DAMAGE;
246	};
247	
248	/** Business the MHPCO refuses to transact. Reported to the customer as-is. */
249	export class ClaimOfficeError extends Error {}
250	
251	/**
252	 * A claim is settled in full or not at all: damaging more items of a type than
253	 * the policy covers rejects the whole claim.
254	 */
255	const rejectOverclaimedTypes = (
256	  damages: Damage[],
257	  policyItems: Item[],
258	): void => {
259	  const covered = countByType(policyItems.map((item) => item.type));
260	  for (const [type, claimed] of countByType(
261	    damages.map((damage) => damage.itemType),
262	  )) {
263	    const insured = covered.get(type) ?? 0;
264	    if (claimed > insured) {
265	      throw new ClaimOfficeError(
266	        `claim covers ${claimed} ${type} damages but the policy insures ${insured}`,
267	      );
268	    }
269	  }
270	};
271	
272	/** Damage is a loss, never a gain. */
273	const rejectNegativeAmounts = (damages: Damage[]): void => {
274	  for (const damage of damages) {
275	    if (damage.amount < 0) {
276	      throw new ClaimOfficeError(
277	        `damage to a ${damage.itemType} cannot be negative: ${damage.amount}`,
278	      );
279	    }
280	  }
281	};
282	
283	const claimResult = (
284	  step: ClaimStep,
285	  policyItems: Item[],
286	  capAlreadyUsed: number,
287	): ClaimResult => {
288	  rejectNegativeAmounts(step.incident.damages);
289	  rejectOverclaimedTypes(step.incident.damages, policyItems);
290	  const claimed = roundPayoutInMHPCOsFavour(
291	    step.incident.damages.reduce(
292	      (total, damage) => total + damagePayout(damage, policyItems),
293	      0,
294	    ),
295	  );
296	  // The cap covers the policy's whole lifetime, so a claim can only draw on
297	  // what earlier claims against the same policy have left.
298	  const capLeft = payoutCap(policyItems) - capAlreadyUsed;
299	  const payout = Math.min(claimed, capLeft);
300	  return { payout, remainingCap: capLeft - payout };
301	};
302	
303	/**
304	 * The items covered by the policy a claim is filed against. A claim's `policy`
305	 * is the index of the quote step that established the policy.
306	 *
307	 * Assumes that step is in fact a quote; no test yet covers a claim pointing at
308	 * a non-quote step, so the assumption is asserted rather than checked.
309	 */
310	const policyItemsFor = (steps: Step[], claim: ClaimStep): Item[] =>
311	  (steps[claim.policy] as QuoteStep).items;
312	
313	/**
314	 * What running the steps so far has established. Steps are settled in order and
315	 * each one reads this, so it carries everything a later step needs to know
316	 * about its predecessors.
317	 */
318	interface Ledger {
319	  /** Results of the steps settled so far, in step order. */
320	  results: StepResult[];
321	  /** Payout drawn against each policy so far, keyed by its quote step's index. */
322	  capUsedByPolicy: ReadonlyMap<number, number>;
323	  /** How many quotes have been settled: the next quote's contract ordinal. */
324	  quotesSoFar: number;
325	}
326	
327	const EMPTY_LEDGER: Ledger = {
328	  results: [],
329	  capUsedByPolicy: new Map(),
330	  quotesSoFar: 0,
331	};
332	
333	const settleQuote = (
334	  step: QuoteStep,
335	  customer: Customer,
336	  ledger: Ledger,
337	): Ledger => ({
338	  ...ledger,
339	  results: [
340	    ...ledger.results,
341	    {
342	      premium: quotePremium(step.items, {
343	        customer,
344	        ordinal: ledger.quotesSoFar,
345	      }),
346	    },
347	  ],
348	  quotesSoFar: ledger.quotesSoFar + 1,
349	});
350	
351	const settleClaim = (
352	  step: ClaimStep,
353	  steps: Step[],
354	  ledger: Ledger,
355	): Ledger => {
356	  const capUsed = ledger.capUsedByPolicy.get(step.policy) ?? 0;
357	  const result = claimResult(step, policyItemsFor(steps, step), capUsed);
358	  return {
359	    ...ledger,
360	    results: [...ledger.results, result],
361	    capUsedByPolicy: new Map(ledger.capUsedByPolicy).set(
362	      step.policy,
363	      capUsed + result.payout,
364	    ),
365	  };
366	};
367	
368	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
369	  const { results } = steps.reduce(
370	    (ledger, step) =>
371	      step.op === "claim"
372	        ? settleClaim(step, steps, ledger)
373	        : settleQuote(step, customer, ledger),
374	    EMPTY_LEDGER,
375	  );
376	  return { results };
377	};
